const priceLevels=(s,side='Long')=>{let p=quote(s),d=side==='Long'?1:-1;return {entry:p,stop:p*(1-d*.008),target:p*(1+d*.018)}};
const pnl=(p,exit=quote(p.symbol))=>(exit-p.entry)*p.qty*(p.side==='Long'?1:-1);
const realized=()=>state.closed.reduce((a,p)=>a+p.pnl,0);
const unrealized=()=>state.positions.reduce((a,p)=>a+pnl(p),0);
const equity=()=>100000+realized()+unrealized();
const available=()=>100000+realized()-state.positions.reduce((a,p)=>a+p.entry*p.qty,0)-state.orders.reduce((a,p)=>a+p.limit*p.qty,0);
