function spark(seed=1,color='var(--green)',wide=false){let pts=Array.from({length:22},(_,i)=>`${i*5},${29-i*.7-Math.sin(i*1.1+seed)*5-Math.cos(i*.6+seed)*3}`).join(' ');return `<svg class="${wide?'wide-chart':'mini'}" viewBox="0 0 110 38" preserveAspectRatio="none" aria-hidden="true"><polyline points="${pts}" stroke="${color}" stroke-width="1.5" fill="none"/></svg>`}
function btn(label,action='',primary=false,ico=''){return `<button class="btn${primary?' primary':''}" ${action?`data-action="${action}"`:''}>${ico?icon(ico,14):''}${label}</button>`}
function head(title,subtitle,actions='',eye='FRYE / WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-actions">${actions}</div></div>`}
function panel(title,body,action='',sub=''){return `<section class="panel"><div class="panel-head"><div><div class="panel-title">${title}</div>${sub?`<div class="panel-sub">${sub}</div>`:''}</div>${action}</div>${body}</section>`}
function stat(label,value,change,note,ico='chart',color='up',seed=1){return `<div class="stat"><div class="stat-label">${label}${icon(ico,14)}</div><div class="stat-value">${value}</div><div class="stat-bottom"><span class="${color}">${change}</span><span>${note}</span></div>${spark(seed,color==='down'?'var(--down)':'var(--green)')}</div>`}
